#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    int64 m;
    cin >> n >> m;

    vector<int64> a(n), b(n);
    for (auto &x : a) cin >> x;
    for (auto &x : b) cin >> x;

    const int64 repetitions = m / 2;
    const int64 totalCloses = static_cast<int64>(n) * m / 2;

    auto rankMask = [&](int mask) -> int64 {
        int64 D = 0, H = 0;

        for (int j = 0; j < n; ++j) {
            int r1 = (2 * j) % n;
            int r2 = (2 * j + 1) % n;

            bool c1 = (mask >> r1) & 1;
            bool c2 = (mask >> r2) & 1;

            int64 d, h;
            if (!c1 && !c2) {
                d = 1;
                h = 0;
            } else if (!c1 && c2) {
                d = 0;
                h = 0;
            } else if (c1 && !c2) {
                d = 0;
                h = 1;
            } else {
                d = -1;
                h = 0;
            }

            H = max(H + d, h);
            D += d;
        }

        int64 slack;
        if (D >= 0) {
            slack = max(repetitions * D,
                        H + (repetitions - 1) * D);
        } else {
            slack = H;
        }

        return totalCloses - slack;
    };

    vector<pair<int64, int>> order;
    for (int i = 0; i < n; ++i)
        order.push_back({b[i] - a[i], i});

    sort(order.begin(), order.end());

    int64 answer = 0;
    for (int i = 0; i < n; ++i)
        answer += m * a[i];

    int mask = 0;
    int64 previousRank = 0;

    for (auto [cost, residue] : order) {
        mask |= 1 << residue;
        int64 currentRank = rankMask(mask);
        answer += (currentRank - previousRank) * cost;
        previousRank = currentRank;
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 INF = (1LL << 60);

using Matrix = vector<vector<int64>>;

Matrix multiply(const Matrix& A, const Matrix& B) {
    int n = (int)A.size();
    Matrix C(n, vector<int64>(n, INF));

    for (int i = 0; i < n; ++i) {
        for (int k = 0; k < n; ++k) {
            if (A[i][k] == INF) continue;
            for (int j = 0; j < n; ++j) {
                if (B[k][j] == INF) continue;
                C[i][j] = min(C[i][j], A[i][k] + B[k][j]);
            }
        }
    }
    return C;
}

Matrix matrixPower(Matrix base, int exponent) {
    int n = (int)base.size();
    Matrix result(n, vector<int64>(n, INF));
    for (int i = 0; i < n; ++i) result[i][i] = 0;

    while (exponent > 0) {
        if (exponent & 1) result = multiply(result, base);
        base = multiply(base, base);
        exponent >>= 1;
    }
    return result;
}

