    int states = maxBoundary + 1;
    int maxBalance = 4 * n;

    Matrix transition(states, vector<int64>(states, INF));

    for (int start = 0; start <= maxBoundary; ++start) {
        vector<int64> dp(maxBalance + 1, INF);
        dp[start] = 0;

        for (int pos = 0; pos < n; ++pos) {
