Matrix multiply(const Matrix& A, const Matrix& B) {
    int n = (int)A.size();
    Matrix C(n, vector<int64>(n, INF));

    for (int i = 0; i < n; ++i) {
        for (int k = 0; k < n; ++k) {
            if (A[i][k] == INF) continue;
            for (int j = 0; j < n; ++j) {
                if (B[k][j] == INF) continue;
                C[i][j] = min(C[i][j], A[i][k] + B[k][j]);
            }
        }
    }
    return C;
}

Matrix power(Matrix base, long long exponent) {
    int n = (int)base.size();
    Matrix result(n, vector<int64>(n, INF));
    for (int i = 0; i < n; ++i) result[i][i] = 0;

    while (exponent > 0) {
        if (exponent & 1LL) result = multiply(result, base);
        exponent >>= 1LL;
        if (exponent > 0) base = multiply(base, base);
    }
    return result;
}

