#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Segment {
    int64 sum;
    int64 suffixMax;
};

Segment combine(const Segment& a, const Segment& b) {
    return {
        a.sum + b.sum,
        max(b.suffixMax, a.suffixMax + b.sum)
    };
}

Segment singleSegment(int value) {
    return {value, max<int64>(0, value)};
}

Segment powerSegment(Segment base, int64 exponent) {
    Segment result{0, 0};
    while (exponent > 0) {
        if (exponent & 1) result = combine(result, base);
        base = combine(base, base);
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    int64 m;
    cin >> n >> m;

    vector<int> a(n), b(n), d(n);
    for (int& x : a) cin >> x;
    for (int& x : b) cin >> x;

    int64 answer = 0;
    for (int i = 0; i < n; ++i) {
        d[i] = a[i] - b[i];
        answer += m * b[i];
    }

    const int64 totalLength = static_cast<int64>(n) * m;
    const int64 openCount = totalLength / 2;
    const int period = n / std::gcd(n, 2);

    int64 previousSelected = 0;

    for (int value = -9; value <= 9; ++value) {
        vector<int> low(n);
        int lowResidues = 0;
        for (int i = 0; i < n; ++i) {
            low[i] = (d[i] <= value);
            lowResidues += low[i];
        }

        int64 totalLowArrivals =
            m * lowResidues - low[n - 1];

        Segment sequence = singleSegment(low[0] - 1);

        Segment cycle{0, 0};
        vector<Segment> cycleParts;
        cycleParts.reserve(period);

        for (int k = 1; k <= period; ++k) {
            int r1 = (2 * k - 1) % n;
            int r2 = (2 * k) % n;
            Segment part = singleSegment(low[r1] + low[r2] - 1);
            cycleParts.push_back(part);
            cycle = combine(cycle, part);
        }

        int64 remainingGroups = openCount - 1;
        int64 fullCycles = remainingGroups / period;
        int remainder = static_cast<int>(remainingGroups % period);

        sequence = combine(sequence, powerSegment(cycle, fullCycles));
        for (int i = 0; i < remainder; ++i) {
            sequence = combine(sequence, cycleParts[i]);
        }

        int64 selectedLow = totalLowArrivals - sequence.suffixMax;
        int64 selectedExactly = selectedLow - previousSelected;
        answer += selectedExactly * value;
        previousSelected = selectedLow;
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<long long> a(n), b(n), d(n);
    for (auto &x : a) cin >> x;
    for (auto &x : b) cin >> x;

    long long sumB = 0;
    for (int i = 0; i < n; ++i) {
        d[i] = a[i] - b[i];
        sumB += b[i];
    }

    long long length = 1LL * n * m;
    long long rounds = length / 2;
    long long pairRounds = rounds - 1;
    int period = n / std::gcd(n, 2);

    auto selectedAtMost = [&](int threshold) -> long long {
        long long first = (d[0] <= threshold);

        vector<long long> y(period);
        for (int j = 0; j < period; ++j) {
            long long r = j + 1;
            int p1 = int((2 * r - 1) % n);
            int p2 = int((2 * r) % n);
            int arrivals = (d[p1] <= threshold) + (d[p2] <= threshold);
            y[j] = arrivals - 1;
        }

        long long fullCycles = pairRounds / period;
        int remainder = int(pairRounds % period);

        long long cycleSum = 0, cycleMin = 0, pref = 0;
        for (long long value : y) {
            pref += value;
            cycleMin = min(cycleMin, pref);
        }
        cycleSum = pref;

        long long remainderSum = 0, remainderMin = 0;
        for (int i = 0; i < remainder; ++i) {
            remainderSum += y[i];
            remainderMin = min(remainderMin, remainderSum);
        }

        long long totalY = fullCycles * cycleSum + remainderSum;
        long long minPrefix = 0;

        if (fullCycles > 0) {
            long long lowestCycleStart = min(0LL, (fullCycles - 1) * cycleSum);
            minPrefix = min(minPrefix, lowestCycleStart + cycleMin);
        }

        minPrefix = min(minPrefix, fullCycles * cycleSum + remainderMin);

        long long queued = totalY - minPrefix;
        long long arrivals = first + pairRounds + totalY;
        return arrivals - queued;
    };

    long long answer = sumB * m;
    long long previous = 0;

    for (int value = -9; value <= 9; ++value) {
        long long current = selectedAtMost(value);
        answer += (current - previous) * value;
        previous = current;
    }

    cout << answer << '\n';
    return 0;
}
